"use strict";

var _LabelsSelector = require("../LabelsSelector.utils");
describe('formatLabelDataFromEdges', function () {
  it('should return an empty array when the provided array is empty', function () {
    expect((0, _LabelsSelector.formatLabelDataFromEdges)()).toEqual([]);
    expect((0, _LabelsSelector.formatLabelDataFromEdges)([])).toEqual([]);
  });
  it('should return the expected results based on the provided data', function () {
    var edges = [{
      node: {
        id: 'abc123',
        name: 'Apples',
        categories: [{
          name: 'Produce'
        }, {
          name: 'Fruit'
        }],
        location: {
          name: 'My Location'
        },
        contentGroup: null
      }
    }, {
      node: {
        id: 'xyz987',
        name: 'Bananas',
        categories: [],
        location: null,
        contentGroup: {
          name: 'My Content Group'
        }
      }
    }, {
      node: {
        id: 'def678',
        name: 'Cherries',
        categories: null,
        location: null,
        contentGroup: {
          name: 'My Publisher'
        }
      }
    }];
    var expectedResult = [{
      value: 'abc123',
      label: 'Apples (Produce, Fruit)',
      ownerName: 'My Location'
    }, {
      value: 'xyz987',
      label: 'Bananas',
      ownerName: 'My Content Group'
    }, {
      value: 'def678',
      label: 'Cherries',
      ownerName: 'My Publisher'
    }];
    expect((0, _LabelsSelector.formatLabelDataFromEdges)(edges)).toEqual(expectedResult);
  });
});
describe('gotoLabelsManagementPage', function () {
  it('redirects to the correct URL', function () {
    Object.defineProperty(window, 'location', {
      writable: true,
      value: {
        assign: jest.fn()
      }
    });
    (0, _LabelsSelector.gotoLabelsManagementPage)();
    expect(window.location.assign).toBeCalledWith(_LabelsSelector.LABEL_MANAGMENT_URL);
  });
});
describe('groupLabelsByOwnerName', function () {
  it('returns the expected value', function () {
    expect((0, _LabelsSelector.groupLabelsByOwnerName)({
      ownerName: 'Jolt'
    })).toEqual('Jolt');
  });
});